  HashlineSnapshotStore store,
  String path,
  String rawContent,
  List<int> seenLines,
) async {
  final normalized = normalizeToLF(stripBom(rawContent).text);
  final canonical = (await env.absolutePath(path)).valueOrNull ?? path;
